<?php
require_once __DIR__.'/../controllers/helpers.php';require_once __DIR__.'/../config/database.php';$user=requireRole(['etudiant']);$q=database()->prepare('SELECT r.note,r.appreciation,r.datePublication,ev.titre,m.idModule,m.libelle FROM resultat r JOIN evaluation ev ON ev.idEvaluation=r.idEvaluation JOIN module m ON m.idModule=ev.idModule WHERE r.idEtudiant=:id ORDER BY r.datePublication DESC');$q->execute(['id'=>$user['id']]);$rows=$q->fetchAll();$pageTitle='Mes résultats';$showSidebar=true;require __DIR__.'/../includes/header.php';?><h2>Mes résultats</h2><div class="card"><table><tr><th>Évaluation</th><th>Module</th><th>Note</th><th>Appréciation</th><th>Publication</th></tr><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['titre'])?></td><td><?=htmlspecialchars('Module '.$row['idModule'].' - '.$row['libelle'])?></td><td><?=htmlspecialchars($row['note'])?> / 20</td><td><?=htmlspecialchars($row['appreciation']??'')?></td><td><?=htmlspecialchars($row['datePublication']??'')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Aucun résultat publié.</td></tr><?php endif;?></table></div><?php require __DIR__.'/../includes/footer.php';?>